{{--
    SocialLoginRow — OAuth provider buttons with SimpleIcons logos.

    <x-auth.social-login-row :providers="AuthEngine::getActiveProviders()" />

    "icon" is raw SVG generated by the package, so it is printed unescaped ({!! !!}).
--}}
@props(['providers' => [], 'dividerLabel' => 'Or continue with'])

@if (count($providers) > 0)
    <div {{ $attributes->merge(['class' => 'space-y-5']) }}>
        @if ($dividerLabel !== '')
            <div class="relative flex items-center">
                <div class="grow border-t border-slate-200"></div>
                <span class="mx-4 shrink-0 text-xs font-medium uppercase tracking-wide text-slate-400">{{ $dividerLabel }}</span>
                <div class="grow border-t border-slate-200"></div>
            </div>
        @endif

        <div class="grid gap-3 {{ count($providers) > 1 ? 'grid-cols-2' : '' }}">
            @foreach ($providers as $provider)
                @php $color = preg_match('/^#[0-9A-Fa-f]{6}$/', (string) ($provider['color'] ?? '')) === 1 ? $provider['color'] : '#111827'; @endphp
                <a href="{{ $provider['url'] }}"
                   class="flex items-center justify-center gap-2.5 rounded-lg bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 shadow-sm ring-1 ring-inset ring-slate-300 transition hover:bg-slate-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600">
                    <span aria-hidden="true" class="h-5 w-5 shrink-0 [&>svg]:h-full [&>svg]:w-full [&>svg]:fill-current" style="color: {{ $color }}">{!! $provider['icon'] !!}</span>
                    <span>{{ $provider['name'] }}</span>
                </a>
            @endforeach
        </div>
    </div>
@endif
